-- Recheck current academic eligibility at the privileged publication boundary.
create or replace function public.finalize_pdf_checked(p_resource uuid,p_author uuid) returns void language plpgsql security definer set search_path='' as $$begin
 if not exists(select 1 from public.account_states where user_id=p_author and status='active') or (not exists(select 1 from public.student_academics s join public.profiles p on p.id=s.user_id join public.universities u on u.id=s.university_id join public.university_faculties uf on uf.university_id=s.university_id and uf.faculty_id=s.faculty_id join public.faculties f on f.id=s.faculty_id join public.academic_years y on y.university_id=s.university_id and y.faculty_id=s.faculty_id and y.year=s.academic_year where s.user_id=p_author and s.completed_at is not null and p.username_claimed and u.is_active and u.onboarding_enabled and f.is_active and uf.is_active) and not exists(select 1 from public.user_roles r join auth.users u on u.id=r.user_id where r.user_id=p_author and r.role='admin' and u.email_confirmed_at is not null)) then raise exception 'active onboarded author required';end if;
 update public.resources r set status='published',file_verified_at=now(),updated_at=now() where r.id=p_resource and r.author_id=p_author and r.status='pending' and r.source_kind='pdf' and exists(select 1 from public.courses c where c.id=r.course_id and c.is_active);
 if not found then raise exception 'pending resource unavailable';end if;end;$$;
